css:
body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 11px;
    color: #000;
}

.company-header {
    margin-bottom: 5px;
}

.company-name {
    font-size: 16px;
    font-weight: bold;
    text-transform: uppercase;
    text-align: left;
    margin-bottom: 5px;
}

.company-address {
    margin-top: 5px;
    line-height: 1.5;
}

.party-section {
    width: 100%;
    margin-top: 5px;
    margin-bottom: 5px;
}

.party-left {
    float: left;
    width: 70%;
}

.party-right {
    float: right;
    width: 25%;
    text-align: right;
}

.clearfix {
    clear: both;
}

.separator {
    border-top: 1px solid #000;
    margin: 5px 0;
}
.details-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0px !important;
    margin-bottom: 0px !important;
}

.details-table td {
    padding: 0px !important;
    line-height: 1.1 !important;
    vertical-align: top;
    border: none !important;
    color:#222;
}

.details-table tr {
    height: 16px !important;
}

.label {
    width: 170px;
    font-weight: bold;
    white-space: nowrap;
}

.value {
    padding-left: 0;
}

.label {
    width: 180px;
    font-weight: bold;
    white-space: nowrap;
    border: none !important;
    padding-right: 10px;
}

.section-title {
    font-weight: bold;
    text-decoration: underline;
    margin-top: 0px !important;
    margin-bottom: 2px !important;
    padding: 0px !important;
}

.adjustment-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    margin-top: 10px;
    font-size: 13px;
}

.adjustment-table th,
.adjustment-table td {
    border: 1px solid #000 !important;
    padding: 1px 3px !important;
    line-height: 1.0 !important;
}

.adjustment-table tr {
    border: 1px solid #000 !important;
}

.adjustment-table tbody tr {
    border-bottom: 1px solid #000 !important;
}

.adjustment-table th {
    text-align: center;
    font-weight: bold;
    background: #f5f5f5;
}

.adjustment-table td {
    vertical-align: middle;
}
.company-header,
.party-section,
.details-table,
.section-title {
    font-size: 13px;
}
.adjustment-table table,
.adjustment-table tr,
.adjustment-table td,
.adjustment-table th {
    border-collapse: collapse !important;
}
.print-format {
    padding: 12px !important;
    margin: 0 !important;
}

p {
    margin: 0;
}

table {
    margin-bottom: 0;
}
.details-table + .section-title {
    margin-top: 0px !important;
}

.print-format p,
.print-format div,
.print-format table {
    margin-bottom: 0px !important;
}
.adjustment-table {
    border-collapse: collapse !important;
    border-spacing: 0 !important;
}

.adjustment-table tr {
    height: 18px !important;
}

.adjustment-table td {
    margin: 0 !important;
}

.adjustment-table th {
    margin: 0 !important;
}

html:
{# ============================================================
   COMPANY DETAILS
   ============================================================ #}

{% set company_doc = frappe.get_doc("Company", doc.company) %}

{% set company_links = frappe.get_all(
    "Dynamic Link",
    filters={
        "link_doctype": "Company",
        "link_name": doc.company,
        "parenttype": "Address"
    },
    fields=["parent"],
    limit=1
) %}

{% set addr = None %}

{% if company_links %}
    {% if frappe.db.exists("Address", company_links[0].parent) %}
        {% set addr = frappe.get_doc("Address", company_links[0].parent) %}
    {% endif %}
{% endif %}


<div class="company-name">
    {{ company_doc.company_name }}
</div>

<div class="company-address">
    {% if addr %}
        {{ addr.address_line1 or "" }}

        {% if addr.address_line2 %}
            , {{ addr.address_line2 }}
        {% endif %}

        {% if addr.city %}
            , {{ addr.city }}
        {% endif %}

        {% if addr.state %}
            , {{ addr.state }}
        {% endif %}

        {% if addr.pincode %}
            {{ addr.pincode }}
        {% endif %}
    {% endif %}
</div>


{# ============================================================
   PARTY DETAILS
   ============================================================ #}

<div class="party-section">

    <div class="party-left">

        <b>To,</b><br>

        {% set links = frappe.get_all(
            "Dynamic Link",
            filters={
                "link_doctype": doc.party_type,
                "link_name": doc.party,
                "parenttype": "Address"
            },
            fields=["parent"],
            limit=1
        ) %}

        {% set b_addr = None %}

        {% if links %}
            {% if frappe.db.exists("Address", links[0].parent) %}
                {% set b_addr = frappe.get_doc("Address", links[0].parent) %}
            {% endif %}
        {% endif %}

        <b>{{ doc.party_name or doc.party }}</b><br>

        {% if b_addr %}

            {{ b_addr.address_line1 or "" }}

            {% if b_addr.address_line2 %}
                , {{ b_addr.address_line2 }}
            {% endif %}

            <br>

            {% if b_addr.city %}
                {{ b_addr.city }}
            {% endif %}

            {% if b_addr.state %}
                , {{ b_addr.state }}
            {% endif %}

            {% if b_addr.pincode %}
                {{ b_addr.pincode }}
            {% endif %}

        {% endif %}

    </div>


    <div class="party-right">

        <b>Date :</b>

        {{ frappe.utils.formatdate(
            frappe.utils.nowdate(),
            "dd-mm-yyyy"
        ) }}

    </div>

</div>


<div class="clearfix"></div>

<div class="separator"></div>

<br>


{# ============================================================
   PAYMENT DETAILS
   ============================================================ #}

<table class="details-table">

<tr>
    <td><b>Bank Name :</b></td>
    <td>{{ doc.paid_from or "" }}</td>
</tr>

<tr>
    <td><b>Cheque No :</b></td>
    <td>{{ doc.reference_no or "" }}</td>
</tr>

<tr>
    <td><b>Cheque Date :</b></td>
    <td>
        {% if doc.reference_date %}
            {{ frappe.utils.formatdate(doc.reference_date) }}
        {% endif %}
    </td>
</tr>

<tr>
    <td><b>Cheque Amount :</b></td>
    <td>{{ doc.paid_amount or "" }}</td>
</tr>

<tr>
    <td><b>Amount In Words :</b></td>
    <td>{{ doc.base_in_words or "" }}</td>
</tr>

<tr>
    <td><b>Reference :</b></td>
    <td>
        {{ doc.name }}

        &nbsp;&nbsp;&nbsp;&nbsp;

        Dated :
        {{ frappe.utils.formatdate(doc.posting_date) }}
    </td>
</tr>

<tr>
    <td><b>Remarks :</b></td>
    <td></td>
</tr>

</table>


<br>


{# ============================================================
   CLEARING ADJUSTMENTS
   ============================================================ #}

<div class="section-title">
    Clearing Adjustments :
</div>

<br>


{% for ref in doc.references %}

    {% if ref.reference_type == "Purchase Invoice" %}

        {# ----------------------------------------------------
           Purchase Invoice safely fetch karo
           ---------------------------------------------------- #}

        {% set pi = None %}

        {% if frappe.db.exists("Purchase Invoice", ref.reference_name) %}
            {% set pi = frappe.get_doc(
                "Purchase Invoice",
                ref.reference_name
            ) %}
        {% endif %}


        {{ loop.index }}.

        Against {{ ref.reference_name }}

        {% if pi %}

            Dated:
            {{ frappe.utils.formatdate(pi.posting_date) }}

            (Doc No:
            {{ pi.bill_no or "" }}

            Doc Dt:
            {% if pi.bill_date %}
                {{ frappe.utils.formatdate(pi.bill_date) }}
            {% endif %}

            Doc Amt:
            Rs. {{ pi.grand_total or 0 }})

        {% endif %}

        Adjusted Amt:
        Rs. {{ ref.allocated_amount or 0 }}

        <br>


        {# ----------------------------------------------------
           Discount / Journal Entry Adjustment
           ---------------------------------------------------- #}

        {% set discount_rows = frappe.db.sql("""
            select
                p.parent as jv_name,
                j.posting_date as jv_date,
                d.account,
                d.debit,
                d.credit
            from `tabJournal Entry Account` p
            inner join `tabJournal Entry` j
                on j.name = p.parent
            inner join `tabJournal Entry Account` d
                on d.parent = p.parent
            where p.reference_type = 'Purchase Invoice'
            and p.reference_name = %s
            and p.party = %s
            and j.docstatus = 1
            and (d.party is null or d.party = '')
        """, (ref.reference_name, doc.party), as_dict=1) %}


        {% for d in discount_rows %}

            &nbsp;&nbsp;&nbsp;&nbsp;

            Against {{ d.jv_name }}

            Dated:
            {{ frappe.utils.formatdate(d.jv_date) }}

            (Account:
            {{ d.account }})

            Discount Amt:
            Rs.
            {{ d.debit or d.credit or 0 }}

            <br>

        {% endfor %}

        <br>

    {% endif %}

{% endfor %}
